window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[282]={"id":"282","numero":282,"titre":"Maladies inflammatoires chroniques de l'intestin (MICI)","objectifs":[{"id":"282-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la maladie de Crohn et de la rectocolite hémorragique","contenu":"<p><span class=\"kw-clinique\">Les</span> <strong><span class=\"kw-etio\">MICI</span></strong> sont des maladies qui résultent de l'<span class=\"kw-def\">inflammation chronique</span>, intermittente ou continue, d'une partie du <span class=\"kw-clinique\">tube digestif</span>. Elles regroupent trois entités :</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Entité</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Maladie de Crohn</span></strong></td><td>Atteinte possible de <strong>tout le tube digestif</strong> (de la bouche à l'anus) ; inflammation <span class=\"kw-def\">transmurale</span> et <strong>discontinue</strong> (intervalles de muqueuse saine)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Rectocolite hémorragique (RCH)</span></strong></td><td>Atteinte limitée au <strong>rectum et au côlon</strong> ; inflammation <span class=\"kw-def\">superficielle</span> et <strong>continue</strong>, à extension rétrograde, sans intervalle sain</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Colite inclassée</span></strong></td><td>Quand la distinction Crohn / <span class=\"kw-etio\">RCH</span> n'est pas possible (<span class=\"kw-chiffre\">5-10 %</span> des cas)</td></tr>\n        </tbody>\n      </table>\n      <p>L'<span class=\"kw-clinique\">évolution</span> se fait le plus souvent par <span class=\"kw-clinique\">poussées</span> de quelques semaines, entrecoupées de périodes de <span class=\"kw-clinique\">rémission</span>.</p>\n      <div class=\"obj-callout warning\">\n        <strong>À retenir.</strong> La distinction Crohn / <span class=\"kw-etio\">RCH</span> devient importante si une <span class=\"kw-alerte\">chirurgie d'exérèse</span> est envisagée. Dans <span class=\"kw-chiffre\">5-10 %</span> des cas elle reste impossible : c'est la <span class=\"kw-etio\">colite inclassée</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 284 — <span class=\"kw-clinique\">Syndrome de l</span>’intestin irritable (SII)</em></p>","frequence":1},{"id":"282-2","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principales lésions macroscopiques et microscopiques de la maladie de Crohn et de la rectocolite hémorragique","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-bio\">biopsies</span> sont réalisées lors de l'<span class=\"kw-imagerie\">endoscopie</span> en <strong>zone lésée ET en zones macroscopiquement saines</strong> (atteinte discontinue dans Crohn, continue dans la <span class=\"kw-etio\">RCH</span>). Lésions communes : <span class=\"kw-def\">ulcérations</span>, <span class=\"kw-def\">raréfaction des glandes</span>, <span class=\"kw-def\">infiltrat lymphoplasmocytaire</span>.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th></th><th><span class=\"kw-etio\">Maladie de Crohn</span></th><th><span class=\"kw-def\">Rectocolite <span class=\"kw-etio\">hémorragique</span></span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Lésions macroscopiques</strong></td>\n            <td>\n              <strong>Topographie :</strong> tout le tube digestif, atteinte <strong>discontinue</strong><br>\n              <strong>Anus :</strong> lésions anopérinéales (≈ <span class=\"kw-chiffre\">50 %</span>)<br>\n              <strong>Rectum :</strong> atteint dans seulement <span class=\"kw-chiffre\">25 %</span><br>\n              <strong>Iléon :</strong> ulcérations iléales (≈ <span class=\"kw-chiffre\">60 %</span>)<br>\n              <strong>Sténoses / fistules :</strong> fréquentes (inflammation <span class=\"kw-def\">transmurale</span>)\n            </td>\n            <td>\n              <strong>Topographie :</strong> rectum + côlon, atteinte <strong>continue sans intervalle sain</strong><br>\n              <strong>Rectum :</strong> atteinte <strong>constante</strong><br>\n              <strong>Extension :</strong> rétrograde, au maximum jusqu'au <strong>cæcum</strong><br>\n              <strong>Anus / iléon :</strong> pas de <span class=\"kw-clinique\">lésion</span> anopérinéale, pas d'ulcération iléale<br>\n              <strong>Sténoses / fistules :</strong> <span class=\"kw-alerte\">jamais</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Inflammation & ulcérations (histo)</strong></td>\n            <td>\n              Inflammation <span class=\"kw-def\">transmurale</span> (toutes <span class=\"kw-clinique\">les</span> couches)<br>\n              Ulcérations <strong>fissuraires</strong><br>\n              <span class=\"kw-def\">Micro-abcès cryptiques</span> : <strong>moins nombreux</strong>\n            </td>\n            <td>\n              Inflammation <span class=\"kw-def\">superficielle</span> (muqueuse + sous-muqueuse superficielle)<br>\n              Ulcérations <strong>non fissuraires</strong><br>\n              <span class=\"kw-def\">Micro-abcès cryptiques</span> : <strong>très nombreux</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Glandes & infiltrat</strong></td>\n            <td>\n              Distorsions glandulaires ; mucosécrétion peu altérée<br>\n              Infiltrat plasmocytaire du chorion, voire transmural, sous forme de <strong><span class=\"kw-def\">nodules lymphoïdes</span></strong><br>\n              <strong><span class=\"kw-alerte\">Granulomes épithélioïdes et gigantocellulaires</span></strong> sans <span class=\"kw-clinique\">nécrose</span> caséeuse : très évocateurs mais présents dans <span class=\"kw-chiffre\">30 %</span> des cas seulement\n            </td>\n            <td>\n              Bifurcations et distorsions glandulaires ; mucosécrétion <strong>très altérée</strong><br>\n              Infiltrat surtout lymphoplasmocytaire du chorion ; <span class=\"kw-def\">plasmocytose basale</span><br>\n              <span class=\"kw-alerte\">Jamais de granulome épithélioïde</span>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout\">\n        <strong>Discriminant clé.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">granulomes épithélioïdes sans nécrose caséeuse</span> orientent vers la <span class=\"kw-etio\">maladie de Crohn</span> ; leur absence et la présence d'une inflammation strictement superficielle continue orientent vers la <span class=\"kw-etio\">RCH</span>.\n      </div>","frequence":0},{"id":"282-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principes physiopathologiques de la maladie de Crohn et de la rectocolite hémorragique","contenu":"<p>La cause des <span class=\"kw-etio\">MICI</span> n'est <strong>pas identifiée</strong> et la <span class=\"kw-def\">physiopathologie</span> reste mal connue. La réaction <span class=\"kw-etio\">inflammatoire</span> qui induit <span class=\"kw-clinique\">les</span> lésions intestinales et extra-intestinales fait intervenir des <span class=\"kw-etio\">facteurs génétiques</span>, des <span class=\"kw-etio\">facteurs environnementaux</span>, le <span class=\"kw-etio\">microbiote fécal (dysbiose)</span> et des <span class=\"kw-etio\">anomalies de la réponse immunitaire</span>.</p>\n      <p>L'inflammation chronique peut entraîner une <span class=\"kw-clinique\">fibrose intestinale</span> évoluant vers une <strong>sténose</strong> (surtout au niveau du grêle dans la <span class=\"kw-etio\">maladie de Crohn</span>) et augmente le risque de <span class=\"kw-alerte\">cancer colorectal</span>.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Facteur</th><th><span class=\"kw-etio\">Maladie de Crohn</span></th><th><span class=\"kw-def\">Rectocolite <span class=\"kw-etio\">hémorragique</span></span></th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Génétique</span></strong></td><td>Mutation <span class=\"kw-def\">CARD15-NOD2</span> (aucune utilité diagnostique)</td><td>Facteurs génétiques sans marqueur spécifique</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Tabac</span></strong></td><td>Effet <span class=\"kw-alerte\">aggravant</span> (<span class=\"kw-chiffre\">30-50 %</span> de fumeurs) → l'<strong>arrêt du <span class=\"kw-etio\">tabac</span> est une priorité</strong></td><td>Effet <strong>protecteur</strong> (<span class=\"kw-chiffre\">&lt; 10 %</span> de fumeurs)</td></tr>\n          <tr><td><strong>Appendicectomie</strong></td><td>ATCD = <strong><span class=\"kw-def\">facteur de risque</span></strong></td><td>ATCD ± facteur <strong>protecteur</strong></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Sérologie</span></strong></td><td><span class=\"kw-bio\">ASCA</span> souvent positifs (pANCA négatifs)</td><td><span class=\"kw-bio\">pANCA</span> souvent positifs (ASCA négatifs)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Épidémiologie</span></strong></td><td><span class=\"kw-def\">Prévalence</span> ≈ <span class=\"kw-chiffre\">1/1000</span> ; <span class=\"kw-def\">incidence</span> <span class=\"kw-chiffre\">5-10/100 000/an</span> ; pic <span class=\"kw-chiffre\">20-30 ans</span></td><td><span class=\"kw-def\">Prévalence</span> ≈ <span class=\"kw-chiffre\">1/1000</span> ; <span class=\"kw-def\">incidence</span> <span class=\"kw-chiffre\">5-10/100 000/an</span> ; adulte jeune + 2<sup>e</sup> pic à <span class=\"kw-chiffre\">60 ans</span></td></tr>\n        </tbody>\n      </table>\n      <p><span class=\"kw-def\">Terrain</span> commun : sujets <strong>jeunes</strong>, sex-ratio ≈ <span class=\"kw-chiffre\">1H/1F</span>, gradient <strong>Nord-Sud</strong> (incidences <span class=\"kw-clinique\">les</span> plus élevées en Amérique du Nord et en Europe septentrionale).</p>\n      <div class=\"obj-callout warning\">\n        <strong>Piège classique.</strong> La mutation <span class=\"kw-def\">CARD15-NOD2</span> n'a <strong>aucune utilité diagnostique</strong> : ne jamais la proposer comme examen pour poser le diagnostic de Crohn.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 197 — Spondylarthrite <span class=\"kw-etio\">inflammatoire</span></em></p>","frequence":0},{"id":"282-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","contenu":"<p>Trois manifestations digestives chroniques sont <span class=\"kw-clinique\">les</span> plus fréquentes et doivent faire évoquer une <span class=\"kw-etio\">MICI</span>, surtout chez un <strong>sujet jeune</strong> : <span class=\"kw-clinique\">diarrhée chronique</span> (sécrétoire ou exsudative), <span class=\"kw-clinique\">douleurs abdominales chroniques</span> et <span class=\"kw-clinique\">amaigrissement / altération de l'état général</span>. Les <strong>symptômes nocturnes qui réveillent le patient</strong> sont un argument fort en faveur d'une cause organique.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Tableau révélateur</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Atteinte rectale / colique (surtout <span class=\"kw-etio\">RCH</span>)</strong></td>\n            <td>\n              <strong><span class=\"kw-clinique\">Rectorragies</span> :</strong> <span class=\"kw-clinique\">constantes dans la RCH</span> (inconstantes dans Crohn)<br>\n              <strong>Syndrome rectal :</strong> évacuations afécales glairo-sanglantes ; <span class=\"kw-clinique\">ténesmes</span> (tension douloureuse calmée par la défécation) ; <span class=\"kw-clinique\">épreintes</span> (sensation de corps étranger intra-rectal)<br>\n              <strong><span class=\"kw-clinique\">Syndrome dysentérique</span> :</strong> <span class=\"kw-clinique\">diarrhée</span> glairo-sanglante chronique\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Atteinte anopérinéale (Crohn)</strong></td>\n            <td>Présente chez ≈ <span class=\"kw-chiffre\">30 %</span> des Crohn (absente dans la <span class=\"kw-etio\">RCH</span>) : <span class=\"kw-clinique\">fistules</span>, <span class=\"kw-clinique\">fissures</span> (parfois indolores, latérales), ulcérations, sténose anale, marisques</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Manifestations extra-digestives</span> inflammatoires</strong></td>\n            <td>\n              <strong>Ophtalmo :</strong> <span class=\"kw-clinique\">uvéite</span>, épisclérite, sclérite<br>\n              <strong>Cutanéo-muqueux :</strong> <span class=\"kw-clinique\">aphtes buccaux</span>, <span class=\"kw-clinique\">érythème noueux</span>, <span class=\"kw-clinique\">pyoderma gangrenosum</span><br>\n              <strong>Articulaire :</strong> <span class=\"kw-clinique\">arthrites</span>, douleurs articulaires\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Comorbidités</span> associées</strong></td>\n            <td>\n              Maladies associées mais <strong>dissociées de l'activité de la <span class=\"kw-etio\">MICI</span></strong> :<br>\n              <strong><span class=\"kw-etio\">Cholangite sclérosante primitive</span> :</strong> plus fréquente dans la <span class=\"kw-etio\">RCH</span>, <span class=\"kw-alerte\">augmente le risque de CCR</span><br>\n              <strong><span class=\"kw-etio\">Spondylarthrite ankylosante</span> :</strong> sacro-iliite radiologique (<span class=\"kw-chiffre\">10-20 %</span>, asymptomatique, évolue parallèlement à l'atteinte digestive) ; forme axiale complète (<span class=\"kw-chiffre\">&lt; 5 %</span>, évolue indépendamment de l'atteinte digestive)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Modes de révélation particuliers</strong></td>\n            <td>Crohn peut débuter comme une <span class=\"kw-clinique\">gastro-entérite</span> dans <span class=\"kw-chiffre\">10 %</span> des cas ; parfois révélé par une complication ; <span class=\"kw-clinique\">masse</span> de la FID possible (<span class=\"kw-clinique\">abcès</span> ou atteinte iléocæcale)</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout danger\">\n        <strong>Piège annale.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-alerte\">ulcérations génitales</span> ne font PAS partie des <span class=\"kw-clinique\">manifestations extra-digestives</span> des <span class=\"kw-etio\">MICI</span> (réponse comptée fausse en annale). Penser à la maladie de <span class=\"kw-clinique\">Behçet</span> devant des ulcérations génitales.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 285 — <span class=\"kw-clinique\">Diarrhée</span> chronique · 284 — <span class=\"kw-clinique\">Syndrome de l</span>’intestin irritable (SII) · 251 — <span class=\"kw-clinique\">Amaigrissement</span> · 197 — Spondylarthrite <span class=\"kw-etio\">inflammatoire</span></em></p>","frequence":7},{"id":"282-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires permettant de poser le diagnostic d’une MICI et les arguments du diagnostic : endocopie, histologie, imagerie (IRM)","contenu":"<p>Le diagnostic repose sur un <strong>faisceau d'arguments</strong> biologiques, endoscopiques, histologiques et radiologiques — aucun examen n'est isolément spécifique.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Examen</th><th>Apport / arguments</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Biologie</strong></td>\n            <td>\n              <strong><span class=\"kw-def\">Syndrome inflammatoire</span> :</strong> <span class=\"kw-bio\">CRP</span> ↑, hyperleucocytose à PNN, thrombocytose<br>\n              <strong>Anémie :</strong> ferriprive, <span class=\"kw-etio\">inflammatoire</span>, ± carence <span class=\"kw-bio\">B12</span> (iléite/résection iléale) ou <span class=\"kw-bio\">folates</span> (grêle proximal)<br>\n              <strong><span class=\"kw-bio\">Albuminémie</span> :</strong> hypoalbuminémie (entéropathie exsudative, dénutrition)\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Calprotectine fécale</span></strong></td>\n            <td>Marqueur le <strong>plus sensible</strong> de l'inflammation intestinale : permet d'<span class=\"kw-bio\">éliminer une MICI active</span> si taux bas, fait le <strong><span class=\"kw-def\">diagnostic différentiel</span> avec le <span class=\"kw-clinique\">syndrome de l</span>'intestin irritable</strong>, et surveille l'<span class=\"kw-clinique\">évolution</span> sous traitement</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-imagerie\">Endoscopie</span></strong></td>\n            <td>\n              <strong><span class=\"kw-imagerie\">FOGD</span> + iléo-<span class=\"kw-imagerie\">coloscopie</span></strong> avec <span class=\"kw-alerte\">biopsies en zone lésée ET en zones macroscopiquement saines</span><br>\n              <strong>Crohn :</strong> ulcérations, <span class=\"kw-clinique\">intervalles de muqueuse saine</span> (différencie de la <span class=\"kw-etio\">RCH</span>), sténoses/fistules possibles<br>\n              <strong><span class=\"kw-etio\">RCH</span> :</strong> inflammation continue débutant à la jonction anorectale, muqueuse granitée, saignement au <span class=\"kw-def\">contact</span>, ulcérations\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Histologie</span></strong></td>\n            <td>Voir objectif « lésions microscopiques » : <span class=\"kw-alerte\">granulomes épithélioïdes sans nécrose caséeuse</span> évocateurs de Crohn (<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>30</span> %</span>) ; inflammation superficielle + micro-<span class=\"kw-clinique\">abcès</span> cryptiques nombreux dans la <span class=\"kw-etio\">RCH</span></td>\n          </tr>\n          <tr>\n            <td><strong>Imagerie</strong></td>\n            <td>\n              <strong>Recherche d'atteinte iléale :</strong> <span class=\"kw-imagerie\">entéro-IRM</span> préférée (pas d'<span class=\"kw-clinique\">irradiation</span>), <span class=\"kw-imagerie\">entéro-TDM</span>, <span class=\"kw-imagerie\">échographie</span><br>\n              <strong>Signes radiologiques de Crohn :</strong> épaississement pariétal segmentaire et asymétrique, <span class=\"kw-imagerie\">signe du peigne</span> (hyperhémie des mésos), sclérolipomatose, <span class=\"kw-clinique\">adénopathies</span> de voisinage, sténoses/fistules<br>\n              <strong>LAP :</strong> <span class=\"kw-imagerie\">IRM pelvienne</span> si atteinte ano-périnéale clinique<br>\n              <strong>Situations douteuses :</strong> <span class=\"kw-imagerie\">vidéocapsule</span> ou <span class=\"kw-imagerie\">entéroscopie</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Sérologies</span> (appoint)</strong></td>\n            <td><span class=\"kw-bio\">ASCA</span> (Crohn) ; <span class=\"kw-bio\">pANCA</span> (<span class=\"kw-etio\">RCH</span>) — leur positivité n'affirme pas le diagnostic. <span class=\"kw-bio\">Coproculture</span> + <span class=\"kw-bio\">EPS</span> pour éliminer une colite infectieuse</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout warning\">\n        <strong>À retenir.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-bio\">biopsies</span> doivent être prélevées <strong>en zone lésée ET en zone saine</strong> ; l'entéro-<span class=\"kw-imagerie\">IRM</span> est privilégiée pour l'atteinte du grêle car elle <span class=\"kw-imagerie\">n'irradie pas</span>.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 284 — <span class=\"kw-clinique\">Syndrome de l</span>’intestin irritable (SII)</em></p>","frequence":4},{"id":"282-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principales complications des MICI","contenu":"<p><span class=\"kw-clinique\">Les</span> complications sont locales, générales et néoplasiques. Certaines sont des <strong>urgences</strong>.</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Type</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Locales (surtout Crohn)</strong></td>\n            <td>\n              <strong>Sténoses</strong> inflammatoires/fibreuses → <span class=\"kw-clinique\">syndrome de Koenig</span> ou occlusion<br>\n              <strong>Fistules</strong> (recto-vaginales, recto-urinaires), <strong><span class=\"kw-clinique\">abcès</span></strong><br>\n              <span class=\"kw-alerte\">Perforation</span>, hémorragies (plus rares)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Colite aiguë grave (surtout <span class=\"kw-etio\">RCH</span>)</strong></td>\n            <td>\n              Présente chez ≈ <span class=\"kw-chiffre\">20 %</span> des <span class=\"kw-etio\">RCH</span>, parfois inaugurale, définie par <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">critères de Truelove-Witts</span><br>\n              <strong>Tableau :</strong> <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">rectorragies</span> abondantes, <span class=\"kw-clinique\">tachycardie</span>, anémie, <span class=\"kw-clinique\">AEG</span><br>\n              <span class=\"kw-alerte\">Complications : colectasie (côlon transverse > <span class=\"kw-chiffre\">6 cm</span>), perforation avec péritonite stercorale, hémorragie massive</span> → <span class=\"kw-alerte\">urgence</span>, <span class=\"kw-alerte\">hospitalisation</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Néoplasique</span></strong></td>\n            <td>\n              Risque de <span class=\"kw-alerte\">cancer colorectal</span> augmenté (et de cancer du grêle dans Crohn, plus rare)<br>\n              <strong><span class=\"kw-def\">Surveillance</span> :</strong> <span class=\"kw-def\">dépistage</span> coloscopique régulier (<span class=\"kw-chiffre\">3-5 ans</span>)<br>\n              <strong>Sur-risque si :</strong> atteinte colique étendue et ancienne, <span class=\"kw-etio\">cholangite sclérosante primitive</span> associée\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Générales</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Anémie</span> multifactorielle, <span class=\"kw-clinique\">dénutrition</span> / hypoalbuminémie<br>\n              <strong>Retard staturo-pondéral</strong> chez l'enfant<br>\n              Accidents <span class=\"kw-alerte\">thrombo-emboliques</span> (favorisés par l'inflammation)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <p>La <strong><span class=\"kw-alerte\">colite aiguë grave</span></strong> est définie par <span class=\"kw-clinique\">les</span> <strong><span class=\"kw-def\">critères de</span> Truelove-Witts</strong> : <strong>1 <span class=\"kw-def\">critère majeur</span> associé à <span class=\"kw-chiffre\">≥ 1</span> critère mineur</strong> (<span class=\"kw-clinique\">poussée</span> modérée si situation intermédiaire).</p>\n      <table class=\"descriptif-table\">\n        <thead><tr><th>Catégorie</th><th>Critères</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Critère majeur</span></strong></td><td>Évacuations hémorragiques <span class=\"kw-chiffre\">&gt; 5/24 h</span></td></tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Critères mineurs</span></strong></td>\n            <td>\n              <span class=\"kw-clinique\">Rectorragies</span> présentes<br>\n              Température <span class=\"kw-chiffre\">≥ 37,5 °C</span><br>\n              Fréquence cardiaque <span class=\"kw-chiffre\">≥ 90/min</span><br>\n              <span class=\"kw-bio\">Hémoglobine</span> <span class=\"kw-chiffre\">&lt; 10 g/dL</span><br>\n              <span class=\"kw-bio\">Vitesse de sédimentation</span> <span class=\"kw-chiffre\">≥ 30 mm</span> (1ʳᵉ heure)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"obj-callout danger\">\n        <strong><span class=\"kw-alerte\">Urgence</span>.</strong> La <span class=\"kw-alerte\">colite aiguë grave</span> (<span class=\"kw-def\">critères de</span> Truelove-Witts) peut se compliquer de <span class=\"kw-alerte\">colectasie</span> et de <span class=\"kw-alerte\">perforation</span> : <span class=\"kw-alerte\">hospitalisation</span> en urgence, <span class=\"kw-imagerie\">TDM</span> systématique pour rechercher perforation/colectasie.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 301 — Tumeur colon - rectum · 213 — Anémie · 250 — Dénutrition</em></p>","frequence":3}],"astuces":[],"liensGlobaux":[{"href":"https://radiopaedia.org/articles/crohn-disease-2","label":"radiopaedia.org"},{"href":"https://radiopaedia.org/articles/ulcerative-colitis","label":"radiopaedia.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Poussée de MICI — Après avoir éliminé une colite infectieuse (coproculture, examen parasitologique des selles)","detail":"<h4>CAT — <span class=\"kw-clinique\">poussée</span> de MICI / colite aiguë grave — Évaluation de la gravité et escalade thérapeutique</h4>","branches":[{"to":"t-non-grave","label":"Critères de Truelove-Witts non remplis (poussée non grave)","color":"green"},{"to":"q-compl","label":"Poussée sévère = colite aiguë grave (≥ 1 critère majeur + ≥ 1 mineur)","color":"red"}]},{"id":"t-non-grave","kind":"terminal","label":"Poussée non grave","color":"green","detail":"<h4>Définition</h4><ul><li><span class=\"kw-clinique\">Poussée</span> légère ou modérée ne remplissant pas <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\"><span class=\"kw-def\">critères de</span> gravité</span> de <span class=\"kw-def\">Truelove-Witts</span></li></ul><h4>PEC</h4><ul><li>Prise en charge non urgente, adaptée à la sévérité et au type de <span class=\"kw-clinique\">MICI</span></li><li>Traitement de fond <em>(modalités hors programme EDN)</em></li></ul>"},{"id":"q-compl","kind":"decision","label":"Complication chirurgicale d'emblée ? — Colectasie (côlon transverse > 6 cm) · perforation · hémorragie digestive massive","branches":[{"to":"t-chirurgie","label":"Oui","color":"red"},{"to":"q-cortico","label":"Non — colite aiguë grave sans complication","color":"amber"}]},{"id":"t-chirurgie","kind":"terminal","label":"Chirurgie en urgence","color":"red","detail":"<h4>Indications</h4><ul><li><span class=\"kw-alerte\">Colectasie</span> : dilatation colique (transverse <span class=\"kw-chiffre\">&gt; 6 cm</span>) + signes toxiques</li><li><span class=\"kw-alerte\">Perforation</span> (<span class=\"kw-alerte\">péritonite stercorale</span>)</li><li><span class=\"kw-alerte\">Hémorragie digestive massive</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Chirurgie en urgence</span> ; <span class=\"kw-imagerie\">TDM</span> systématique devant toute colite aiguë grave (recherche perforation / colectasie)</li></ul>"},{"id":"q-cortico","kind":"decision","label":"Corticoïdes IV 5 jours — réponse à J5 ? — Traitement médical initial de la colite aiguë grave","branches":[{"to":"t-repondeur","label":"Réponse favorable","color":"green"},{"to":"t-2eligne","label":"Échec à J5 (corticorésistance)","color":"red"}]},{"id":"t-repondeur","kind":"terminal","label":"Répondeur aux corticoïdes IV","color":"green","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Corticoïdes IV</span> pendant <span class=\"kw-chiffre\">5 jours</span>, réponse favorable</li></ul><h4>Suite</h4><ul><li>Relais et traitement de fond, <span class=\"kw-clinique\">surveillance</span> rapprochée</li><li><span class=\"kw-def\">Suivi</span> de l'activité par <span class=\"kw-bio\">calprotectine fécale</span> / <span class=\"kw-bio\">CRP</span></li></ul>"},{"id":"t-2eligne","kind":"terminal","label":"2ᵉ ligne médicale → colectomie de sauvetage","color":"red","detail":"<h4>2ᵉ ligne médicale</h4><ul><li><span class=\"kw-ttt\">Ciclosporine IV</span> si <span class=\"kw-etio\">RCH</span></li><li><span class=\"kw-ttt\">Infliximab</span> si <span class=\"kw-etio\">maladie de Crohn</span></li></ul><h4>Échec de la 2ᵉ ligne</h4><ul><li><span class=\"kw-ttt\">Colectomie de sauvetage</span> — le traitement chirurgical n'intervient qu'en cas d'échec du traitement médical</li></ul>"}]},"cards":[{"i":"37712e6c89e4","n":282,"o":"282-1","u":"Définition","t":"Connaître la définition de la maladie de Crohn et de la rectocolite hémorragique","q":"Quelles sont les caractéristiques de l'atteinte digestive dans la Maladie de Crohn ?","a":"<p>La Maladie de Crohn peut atteindre <strong>tout le tube digestif</strong>, de la bouche à l'anus. L'inflammation est <strong>transmurale</strong> et <strong>discontinue</strong>, avec des intervalles de muqueuse saine.</p>"},{"i":"4cd91bc7f9b6","n":282,"o":"282-1","u":"Définition","t":"Connaître la définition de la maladie de Crohn et de la rectocolite hémorragique","q":"Quelle est la définition générale des Maladies Inflammatoires Chroniques de l'Intestin (MICI) ?","a":"<p>Les MICI sont des maladies caractérisées par une <strong>inflammation chronique</strong>, intermittente ou continue, d'une partie du tube digestif.</p>"},{"i":"ed1cdc12989e","n":282,"o":"282-1","u":"Définition","t":"Connaître la définition de la maladie de Crohn et de la rectocolite hémorragique","q":"Quelles sont les caractéristiques de l'atteinte digestive dans la Rectocolite Hémorragique (RCH) ?","a":"<p>La Rectocolite Hémorragique (RCH) est limitée au <strong>rectum et au côlon</strong>. L'inflammation est <strong>superficielle et continue</strong>, avec une extension rétrograde et sans intervalle sain.</p>"},{"i":"171974408309","n":282,"o":"282-4","u":"Diagnostic positif","t":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","q":"Quelles sont les comorbidités associées aux MICI qui peuvent être dissociées de l'activité intestinale ?","a":"<p>Les comorbidités associées mais dissociées de l'activité des MICI sont :</p><ul><li>La <strong>cholangite sclérosante primitive</strong> : plus fréquente dans la RCH, elle augmente le risque de carcinome colorectal.</li><li>La <strong>spondylarthrite ankylosante</strong> :<br><ul><li>Forme avec <strong>sacro-iliite radiologique</strong> (10-20 %) : souvent asymptomatique, elle évolue parallèlement à l'atteinte digestive.</li><li>Forme axiale complète (< 5 %) : elle évolue indépendamment de l'atteinte digestive.</li></ul></li></ul>"},{"i":"22c08dbe0d49","n":282,"o":"282-4","u":"Diagnostic positif","t":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","q":"Quelles sont les trois manifestations digestives chroniques les plus fréquentes qui doivent faire évoquer une maladie inflammatoire chronique de l'intestin (MICI), en particulier chez un sujet jeune ?","a":"<p>Les trois manifestations digestives chroniques les plus fréquentes évoquant une MICI, surtout chez un sujet jeune, sont :</p><ul><li>Une <strong>diarrhée chronique</strong> (sécrétoire ou exsudative)</li><li>Des <strong>douleurs abdominales chroniques</strong></li><li>Un <strong>amaigrissement</strong> ou une altération de l'état général</li></ul><p>La présence de <strong>symptômes nocturnes</strong> qui réveillent le patient est un argument fort en faveur d'une cause organique.</p>"},{"i":"366b54352c80","n":282,"o":"282-4","u":"Diagnostic positif","t":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","q":"Quels sont les modes de révélation particuliers de la Maladie de Crohn, et quel est un piège classique à éviter concernant les manifestations extra-digestives ?","a":"<p>La Maladie de Crohn peut se révéler de différentes manières :</p><ul><li>Elle peut débuter comme une <strong>gastro-entérite</strong> dans <strong>10 %</strong> des cas.</li><li>Elle peut être révélée par une <strong>complication</strong>.</li><li>La présence d'une <strong>masse de la fosse iliaque droite</strong> (abcès ou atteinte iléo-cæcale) est possible.</li></ul><p>Un piège classique est de considérer les <strong>ulcérations génitales</strong> comme faisant partie des manifestations extra-digestives des MICI (ce qui est faux). Il faut plutôt penser à la <strong>maladie de Behçet</strong> devant des ulcérations génitales.</p>"},{"i":"665745114a0d","n":282,"o":"282-4","u":"Diagnostic positif","t":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","q":"Quelles sont les principales manifestations extra-digestives inflammatoires que l'on peut rencontrer au cours des MICI ?","a":"<p>Les principales manifestations extra-digestives inflammatoires des MICI sont :</p><ul><li><strong>Ophtalmologiques</strong> : <strong>uvéite</strong>, épisclérite, sclérite.</li><li><strong>Cutanéo-muqueuses</strong> : <strong>aphtes buccaux</strong>, <strong>érythème noueux</strong>, <strong>pyoderma gangrenosum</strong>.</li><li><strong>Articulaires</strong> : <strong>arthrites</strong>, douleurs articulaires.</li></ul>"},{"i":"bb295e8b2fdb","n":282,"o":"282-4","u":"Diagnostic positif","t":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","q":"Quelles sont les différentes manifestations anopérinéales pouvant survenir dans la Maladie de Crohn, et quelle est leur fréquence ?","a":"<p>Les manifestations anopérinéales sont présentes chez environ <strong>30 %</strong> des patients atteints de Maladie de Crohn et sont absentes dans la Rectocolite Hémorragique. Elles peuvent inclure :</p><ul><li>Des <strong>fistules</strong></li><li>Des <strong>fissures</strong> (parfois indolores, latérales)</li><li>Des <strong>ulcérations</strong></li><li>Une <strong>sténose anale</strong></li><li>Des <strong>marisques</strong></li></ul>"},{"i":"c8ca75123ac1","n":282,"o":"282-4","u":"Diagnostic positif","t":"Connaître les situations cliniques révélatrices d’une maladie inflammatoire chroniques de l’intestin (MICI)","q":"Quelles sont les manifestations d'une atteinte recto-colique pouvant orienter vers une MICI, en particulier la Rectocolite Hémorragique (RCH) ?","a":"<p>Les manifestations d'une atteinte recto-colique évocatrices d'une MICI sont :</p><ul><li>Des <strong>rectorragies</strong>, constantes dans la RCH mais inconstantes dans la maladie de Crohn.</li><li>Un <strong>syndrome rectal</strong> : évacuations <strong>afécales glairo-sanglantes</strong>, <strong>ténesmes</strong> (tension douloureuse calmée par la défécation) et <strong>épreintes</strong> (sensation de corps étranger intra-rectal).</li><li>Un <strong>syndrome dysentérique</strong> : diarrhée glairo-sanglante chronique.</li></ul>"},{"i":"1b814499f3fe","n":282,"o":"282-6","u":"Diagnostic positif","t":"Connaître les principales complications des MICI","q":"Quelles sont les complications néoplasiques associées aux MICI et leur surveillance ?","a":"<p>Le risque de <strong>cancer colorectal</strong> est augmenté (ainsi que de cancer du grêle dans la maladie de Crohn, plus rare).</p><p>La surveillance est un <strong>dépistage coloscopique régulier</strong> (tous les <strong>3 à 5 ans</strong>). Le sur-risque est majoré en cas d'atteinte colique étendue et ancienne, ou de cholangite sclérosante primitive associée.</p>"},{"i":"5e98b2b0f90d","n":282,"o":"282-6","u":"Diagnostic positif","t":"Connaître les principales complications des MICI","q":"Quelles sont les principales complications locales des MICI, en particulier de la maladie de Crohn ?","a":"<p>Les complications locales des MICI sont :</p><ul><li>Les <strong>sténoses inflammatoires/fibreuses</strong> pouvant entraîner un <strong>syndrome de Koenig</strong> ou une occlusion.</li><li>Les <strong>fistules</strong> (recto-vaginales, recto-urinaires) et les <strong>abcès</strong>.</li><li>Plus rarement, la <strong>perforation</strong> ou les <strong>hémorragies</strong>.</li></ul>"},{"i":"8f1648302fee","n":282,"o":"282-6","u":"Diagnostic positif","t":"Connaître les principales complications des MICI","q":"Comment est définie la colite aiguë grave (CAG) et quelles sont ses complications ?","a":"<p>La colite aiguë grave (CAG), présente chez environ <strong>20% des RCH</strong>, est définie par les <strong>critères de Truelove-Witts</strong>. Elle se manifeste par une <strong>fièvre</strong>, des <strong>rectorragies abondantes</strong>, une tachycardie, une anémie et un AEG.</p><p>Ses complications sont une <strong>colectasie</strong> (côlon transverse > 6 cm), une <strong>perforation avec péritonite stercorale</strong> et une <strong>hémorragie massive</strong>. C'est une <strong>urgence</strong> nécessitant une hospitalisation.</p>"},{"i":"c5d7cba33453","n":282,"o":"282-6","u":"Diagnostic positif","t":"Connaître les principales complications des MICI","q":"Quels sont les critères de Truelove-Witts pour définir la colite aiguë grave ?","a":"<p>La colite aiguë grave est définie par <strong>1 critère majeur</strong> associé à <strong>≥ 1 critère mineur</strong> :</p><ul><li><strong>Critère majeur</strong> : Évacuations hémorragiques <strong>> 5/24 h</strong>.</li><li><strong>Critères mineurs</strong> :<ul><li>Rectorragies présentes.</li><li>Température <strong>≥ 37,5 °C</strong>.</li><li>Fréquence cardiaque <strong>≥ 90/min</strong>.</li><li>Hémoglobine <strong>< 10 g/dL</strong>.</li><li>Vitesse de sédimentation <strong>≥ 30 mm</strong> (1ʳᵉ heure).</li></ul></li></ul>"},{"i":"f1c02828c314","n":282,"o":"282-6","u":"Diagnostic positif","t":"Connaître les principales complications des MICI","q":"Quelles sont les complications générales des MICI ?","a":"<p>Les complications générales des MICI sont :</p><ul><li>L'<strong>anémie multifactorielle</strong>.</li><li>La <strong>dénutrition / hypoalbuminémie</strong>.</li><li>Le <strong>retard staturo-pondéral</strong> chez l'enfant.</li><li>Les <strong>accidents thrombo-emboliques</strong>, favorisés par l'inflammation.</li></ul>"}]};